)

func main() {
	m := map[string]int{"b": 2, "a": 1, "c": 3}
	keys := make([]string, 0, len(m)) // collect keys
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)                // sort for deterministic order
	for _, k := range keys {          // range the sorted keys
		fmt.Println(k, m[k])
	}
}

